"""Compiled checks for AELLO-C8-S6. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

One graded object: a scored box list per graded image, at /submission/detections.json. One graded
quantity: the share of the private split whose TOP-SCORING box reaches IoU 0.5 against that
image's single ground-truth box. Every check below runs against delivered bytes -- the submitted
box lists, the shipped image and box indexes, and the record the graded run wrote -- and
references no unmeasured quantity, except correct_localisation_rate_at_iou_half, which raises ConstantUnmeasured while
tests/constants.json carries nulls.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
BUNDLE = os.path.dirname(HERE)
SUBMISSION = '/submission/detections.json'

# The corpus layout, from solution/grounding.yaml. The graded IMAGES are agent-visible because the
# agent has to predict on them; the graded BOXES are not, and red line 1 is what keeps the
# distinction. The trimap directory is named so that its ABSENCE can be checked.
GRADED_IMAGE_INDEX = os.path.join(BUNDLE, 'environment/data/graded_images.json')
LABELLED_BOX_INDEX = os.path.join(BUNDLE, 'environment/data/labelled_boxes.json')
TRAINING_IMAGE_INDEX = os.path.join(BUNDLE, 'environment/data/training_images.json')
GRADED_BOXES = os.path.join(BUNDLE, 'tests/heldout/graded_boxes.json')
WITHHELD_TRIMAP_DIR = os.path.join(BUNDLE, 'environment/data/annotations/trimaps')
RUN_RECORD = os.path.join(BUNDLE, 'run_record.json')

# Constants of the METRIC, not measurements of this slot. IOU_THRESHOLD is where
# correct-localisation is defined; floor, knee and the dichotomizing threshold stay null.
IOU_THRESHOLD = 0.5
BOX_ORDER = ('x1', 'y1', 'x2', 'y2')
TRIMAP_TOKENS = ('trimap', 'trimaps', 'pixel_mask', 'segmentation_mask')
GUARDED_WRITES = ('/tests/', 'graded_boxes.json', 'labelled_boxes.json', 'graded_images.json')

CHECKS = []


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "AELLO-C8-S6: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}


@check(id="box_supervision_confined_to_the_labelled_fraction", weight=5, knockout=True, kind="integrity")
def test_box_supervision_confined_to_the_labelled_fraction():
    labelled = set(labelled_image_ids())
    if not labelled:
        return False, evidence(target="run_record", reason="labelled_box_index_unavailable",
                               path=LABELLED_BOX_INDEX)
    declared = declared_ids("box_supervised_image_ids")
    if declared is None:
        return False, evidence(target="run_record", reason="no_box_supervision_declaration")
    beyond = sorted(declared - labelled)
    training = training_image_ids()
    shipped = (len(labelled) / float(len(training))) if training else None
    stated = as_number(run_record().get("labelled_fraction"))
    misdeclared = shipped is not None and (stated is None or abs(stated - shipped) > 1e-6)
    reason = ("box_read_outside_the_labelled_fraction" if beyond else
              "declared_fraction_is_not_the_shipped_fraction" if misdeclared else None)
    return (reason is None), evidence(target="run_record", labelled_images=len(labelled),
                                      declared_images=len(declared),
                                      beyond_the_fraction=beyond[:6], shipped_fraction=shipped,
                                      declared_fraction=stated, reason=reason)


@check(id="boxes_in_native_pixel_frame", weight=4, knockout=True, kind="deliverable")
def test_boxes_in_native_pixel_frame():
    try:
        table = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    sizes = graded_image_sizes()
    if not sizes:
        return False, evidence(reason="graded_image_index_unavailable", path=GRADED_IMAGE_INDEX)
    no_area, outside, widest = [], [], 0.0
    for image in sorted(sizes):
        entry = table.get(image)
        if entry is None:
            continue
        try:
            boxes = parsed_boxes(entry)
        except Exception:
            continue
        width, height = sizes[image]
        for coords, _ in boxes:
            widest = max(widest, coords[2], coords[3])
            if not (coords[2] > coords[0] and coords[3] > coords[1]):
                no_area.append("%s:%s" % (image, coords))
            elif (coords[0] < 0 or coords[1] < 0 or coords[2] > width or coords[3] > height):
                outside.append("%s:%s>%dx%d" % (image, coords, width, height))
    normalised = 0.0 < widest <= 1.0
    reason = ("every_coordinate_at_most_one_so_the_boxes_are_normalised" if normalised else
              "box_has_no_positive_area" if no_area else
              "box_leaves_its_own_image" if outside else None)
    return (reason is None), evidence(images_with_a_published_frame=len(sizes),
                                      widest_coordinate=widest, boxes_without_area=no_area[:6],
                                      boxes_outside_their_image=outside[:6], reason=reason)


@check(id="checker_tree_and_box_indexes_untouched", weight=5, knockout=True, kind="integrity")
def test_checker_tree_and_box_indexes_untouched():
    written = declared_paths("paths_written")
    if written is None:
        return False, evidence(target="submitted_source", reason="no_write_manifest")
    guarded = sorted(path for path in written if in_guarded_tree(path))
    return (not guarded), evidence(target="submitted_source", paths_written=len(written),
                                   guarded_paths_written=guarded[:6],
                                   reason=None if not guarded else "wrote_into_a_guarded_path")


@check(id="correct_localisation_rate_at_iou_half", weight=10, knockout=True, kind="outcome")
def test_correct_localisation_rate_at_iou_half():
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    rate = measure()
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (rate - c["floor"]) / span))
    return rate >= c["dichotomizing_threshold"], evidence(correct_localisation_rate=rate,
                                                          iou_threshold=IOU_THRESHOLD,
                                                          s_outcome=s)


@check(id="detections_manifest_lands", weight=5, knockout=True, kind="deliverable")
def test_detections_manifest_lands():
    if not os.path.exists(SUBMISSION):
        return False, evidence(reason="submission_missing", path=SUBMISSION)
    try:
        table = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    malformed = []
    for image in sorted(table):
        try:
            parsed_boxes(table[image])
        except Exception as exc:
            malformed.append("%s: %s" % (image, exc))
    return (not malformed), evidence(path=SUBMISSION, images=len(table), shape=describe(table),
                                     malformed_lists=malformed[:6],
                                     reason=None if not malformed
                                     else "box_record_is_not_a_box_and_a_score")


@check(id="localisation_budget_declared", weight=3, knockout=False, kind="process")
def test_localisation_budget_declared():
    declaration = run_record().get("agent_budget_declaration")
    if not isinstance(declaration, dict):
        return False, evidence(target="run_record", reason="no_agent_declaration")
    used = as_number(declaration.get("labelled_images_used"))
    seconds = as_number(declaration.get("graded_run_seconds"))
    optimised_for = as_number(declaration.get("optimised_for_iou"))
    scales = declaration.get("inference_scales")
    numeric = ([as_number(scale) for scale in scales] if isinstance(scales, list) else [])
    usable_scales = (bool(numeric) and None not in numeric and min(numeric) > 0.0
                     and len(set(numeric)) == len(numeric))
    labelled = len(labelled_image_ids())
    reason = ("declaration_incomplete" if None in (used, seconds, optimised_for) else
              "inference_scales_are_not_distinct_positive_numbers" if not usable_scales else
              "optimised_for_an_iou_this_slot_does_not_grade"
              if abs(optimised_for - IOU_THRESHOLD) > 1e-9 else
              "declared_more_labelled_images_than_the_fraction_ships"
              if labelled and used > labelled else None)
    return (reason is None), evidence(target="run_record", labelled_images_used=used,
                                      labelled_images_shipped=labelled, graded_run_seconds=seconds,
                                      inference_scales=numeric, optimised_for_iou=optimised_for,
                                      reason=reason)


@check(id="no_abstention_every_graded_image_localised", weight=5, knockout=True, kind="deliverable")
def test_no_abstention_every_graded_image_localised():
    try:
        table = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    graded = graded_image_ids()
    if not graded:
        return False, evidence(reason="graded_image_index_unavailable", path=GRADED_IMAGE_INDEX)
    unanswered, empty = [], []
    for image in graded:
        entry = table.get(image)
        if entry is None:
            unanswered.append(image)
        elif isinstance(entry, list) and not entry:
            empty.append(image)
    reason = ("graded_image_carries_no_entry" if unanswered else
              "graded_image_carries_an_empty_box_list" if empty else None)
    return (reason is None), evidence(graded_images=len(graded), answered=len(table),
                                      unanswered=unanswered[:6], empty_lists=empty[:6],
                                      reason=reason)


@check(id="private_split_boxes_unread", weight=5, knockout=True, kind="integrity")
def test_private_split_boxes_unread():
    graded = set(graded_image_ids())
    if not graded:
        return False, evidence(target="run_record", reason="graded_image_index_unavailable",
                               path=GRADED_IMAGE_INDEX)
    declared = declared_ids("box_supervised_image_ids")
    opened = declared_paths("paths_read")
    if declared is None or opened is None:
        return False, evidence(target="run_record",
                               reason="no_box_supervision_declaration" if declared is None
                               else "no_read_declaration")
    from_the_answer_key = sorted(declared & graded)
    private_reads = sorted(path for path in opened
                           if os.path.basename(GRADED_BOXES) in path or "heldout" in path)
    reason = ("trained_on_a_graded_image_box" if from_the_answer_key else
              "opened_the_private_box_index" if private_reads else None)
    return (reason is None), evidence(target="run_record", graded_images=len(graded),
                                      graded_boxes_consumed=from_the_answer_key[:6],
                                      private_reads=private_reads[:6], reason=reason)


@check(id="pseudo_boxes_gated_and_disjoint_from_labelled", weight=4, knockout=False, kind="process")
def test_pseudo_boxes_gated_and_disjoint_from_labelled():
    accounting = run_record().get("pseudo_box_accounting")
    if not isinstance(accounting, dict):
        return False, evidence(target="run_record", reason="no_pseudo_box_accounting")
    proposed = as_number(accounting.get("proposed"))
    retained = as_number(accounting.get("retained"))
    gate = as_number(accounting.get("confidence_gate"))
    if proposed is None or retained is None or gate is None:
        return False, evidence(target="run_record", reason="pseudo_box_accounting_incomplete",
                               declared_keys=sorted(accounting))
    placed = declared_ids("pseudo_box_image_ids")
    labelled = set(labelled_image_ids())
    already_labelled = sorted(placed & labelled) if placed is not None else []
    reason = ("no_pseudo_box_image_ids_declared" if placed is None else
              "confidence_gate_is_not_a_probability" if not 0.0 < gate < 1.0 else
              "retained_more_pseudo_boxes_than_it_proposed" if retained > proposed else
              "pseudo_box_placed_on_an_image_that_already_carries_one" if already_labelled else
              "gate_admitted_every_proposed_pseudo_box"
              if proposed > 0 and retained == proposed else None)
    return (reason is None), evidence(target="run_record", proposed=proposed, retained=retained,
                                      confidence_gate=gate,
                                      images_receiving_a_pseudo_box=0 if placed is None
                                      else len(placed),
                                      on_already_labelled_images=already_labelled[:6],
                                      reason=reason)


@check(id="top_box_replay_digest", weight=3, knockout=False, kind="process")
def test_top_box_replay_digest():
    stated = run_record().get("replay_top_box_sha256")
    if not isinstance(stated, str) or not stated.strip():
        return False, evidence(target="submitted_source", reason="no_replay_digest_declared")
    try:
        observed = decisive_digest()
    except Exception as exc:
        return False, evidence(target="submitted_source", reason="submission_malformed",
                               error=str(exc))
    stated = stated.strip().lower()
    return stated == observed, evidence(target="submitted_source", declared=stated[:16],
                                        observed=observed[:16],
                                        reason=None if stated == observed
                                        else "replay_moved_a_top_box")


@check(id="top_scoring_box_is_unambiguous", weight=4, knockout=True, kind="deliverable")
def test_top_scoring_box_is_unambiguous():
    try:
        table = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    tied, unusable = [], []
    for image in sorted(table):
        try:
            boxes = parsed_boxes(table[image])
        except Exception as exc:
            unusable.append("%s: %s" % (image, exc))
            continue
        if not boxes:
            continue
        scores = [score for _, score in boxes]
        best = max(scores)
        if scores.count(best) != 1:
            tied.append("%s: %d boxes at %r" % (image, scores.count(best), best))
    reason = ("box_score_is_not_a_finite_number" if unusable else
              "two_boxes_share_the_top_score" if tied else None)
    return (reason is None), evidence(images=len(table), tied_at_the_top=tied[:6],
                                      unusable_scores=unusable[:6], reason=reason)


@check(id="trimaps_withheld_and_unread", weight=4, knockout=True, kind="integrity")
def test_trimaps_withheld_and_unread():
    present = tree_holds_trimaps()
    opened = declared_paths("paths_read")
    if opened is None:
        return False, evidence(target="submitted_source", reason="no_read_declaration")
    reads = sorted(path for path in opened if names_a_trimap(path))
    reason = ("withheld_trimap_directory_is_present_in_the_delivered_tree" if present else
              "graded_run_declares_a_trimap_read" if reads else None)
    return (reason is None), evidence(target="submitted_source", trimap_dir=WITHHELD_TRIMAP_DIR,
                                      trimap_dir_present=present, declared_reads=len(opened),
                                      trimap_reads=reads[:6], reason=reason)


# ------------------------------------------------------------------------------------------
# Reading the delivered bytes. Three shipped indexes, one private box index and one record,
# each read the same way every check reads it: absent is reported, never guessed at.
# ------------------------------------------------------------------------------------------

def load_submission():
    """The scored box lists: one per graded image id, under the `detections` member."""
    with open(SUBMISSION) as handle:
        doc = json.load(handle)
    if not isinstance(doc, dict):
        raise ValueError("the deliverable must be a JSON object, not a %s" % type(doc).__name__)
    table = doc.get("detections")
    if not isinstance(table, dict):
        raise ValueError("the deliverable carries no `detections` object keyed by image id")
    if not table:
        raise ValueError("`detections` names no graded image")
    return dict((str(image), entry) for image, entry in table.items())


def describe(table):
    return ",".join("%s:%d" % (image, len(table[image]) if isinstance(table[image], list) else -1)
                    for image in sorted(table)[:4])


def json_index(path):
    """One shipped index as an image-keyed mapping; empty when it will not read.

    Empty covers two cases and the checks distinguish them by what else is available: the index
    has not landed in this tree, or it landed and no longer parses. The second is a write into a
    guarded path happening in front of the verifier, so it must produce a report rather than an
    unhandled traceback -- an index that will not open is a finding, not a crash.
    """
    if not os.path.exists(path):
        return {}
    try:
        with open(path) as handle:
            doc = json.load(handle)
    except Exception:
        return {}
    return dict((str(k), v) for k, v in doc.items()) if isinstance(doc, dict) else {}


def graded_image_sizes():
    """graded image id -> (width, height): the native frame that image's boxes are scored in."""
    sizes = {}
    for image, meta in json_index(GRADED_IMAGE_INDEX).items():
        if not isinstance(meta, dict):
            continue
        try:
            width, height = int(meta["width"]), int(meta["height"])
        except Exception:
            continue
        if width > 0 and height > 0:
            sizes[image] = (width, height)
    return sizes


def graded_image_ids():
    """The graded split. The private box index names it; the shipped image index stands in.

    Verifier-side both are mounted and they agree. In a staged tree neither may have landed, and
    every check that needs the split says so rather than passing over an empty one.
    """
    for source in (GRADED_BOXES, GRADED_IMAGE_INDEX):
        table = json_index(source)
        if table:
            return sorted(table)
    return []


def labelled_image_ids():
    """The fixed small fraction: the only training images whose ground-truth box ships."""
    return sorted(json_index(LABELLED_BOX_INDEX))


def training_image_ids():
    """Every training image, labelled or not. Its size is the fraction's denominator."""
    return sorted(json_index(TRAINING_IMAGE_INDEX))


def as_number(value):
    """A finite number, or None. Booleans are not numbers here: True is a declaration, not 1."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    number = float(value)
    if number != number or number in (float("inf"), float("-inf")):
        return None
    return number


def parsed_boxes(entry):
    """Every (coords, score) in one image's list. Raises on anything that is not a box list."""
    if not isinstance(entry, list):
        raise ValueError("the entry is a %s, not a list of scored boxes" % type(entry).__name__)
    parsed = []
    for record in entry:
        if not isinstance(record, dict):
            raise ValueError("a record is a %s, not an object with a box and a score"
                             % type(record).__name__)
        box, score = record.get("box"), record.get("score")
        if not isinstance(box, list) or len(box) != 4:
            raise ValueError("a record's box is not four coordinates in the order %s"
                             % ",".join(BOX_ORDER))
        coords = [as_number(value) for value in box]
        if None in coords:
            raise ValueError("a box coordinate is not a finite number: %r" % (box,))
        number = as_number(score)
        if number is None:
            raise ValueError("a box carries score %r, which is not a finite number" % (score,))
        parsed.append((coords, number))
    return parsed


def top_box(entry):
    """The one box correct-localisation reads, with the reason there is none.

    Returns (coords, reason). A tie at the top is NOT resolved here by taking the first: the
    graded binary would then be a property of the writer's iteration order rather than of the
    model, which is exactly what top_scoring_box_is_unambiguous refuses.
    """
    boxes = parsed_boxes(entry)
    if not boxes:
        return None, "empty_box_list"
    best = max(score for _, score in boxes)
    winners = [coords for coords, score in boxes if score == best]
    if len(winners) != 1:
        return None, "tied_top_score"
    return winners[0], None


def intersection_over_union(a, b):
    """Half-open pixel rectangles: width is x2 - x1, so a zero-width box has no area."""
    overlap_x = max(0.0, min(a[2], b[2]) - max(a[0], b[0]))
    overlap_y = max(0.0, min(a[3], b[3]) - max(a[1], b[1]))
    intersection = overlap_x * overlap_y
    area_a = max(0.0, a[2] - a[0]) * max(0.0, a[3] - a[1])
    area_b = max(0.0, b[2] - b[0]) * max(0.0, b[3] - b[1])
    union = area_a + area_b - intersection
    return 0.0 if union <= 0.0 else intersection / union


def decisive_digest():
    """sha256 over the decision, not over the file.

    One line per submitted image in sorted id order: the top box's four coordinates floored to
    their integer pixel, or `none` where the list is empty or its top score is tied. Reordering
    the inert boxes below the top one changes no localisation and must not read as divergence;
    a top box that moves one pixel can cross IoU %s and flip a graded image, so it must.
    """ % IOU_THRESHOLD
    import hashlib
    import math
    table = load_submission()
    digest = hashlib.sha256()
    for image in sorted(table):
        try:
            coords, _ = top_box(table[image])
        except Exception:
            coords = None
        if coords is None:
            digest.update(("%s|none\n" % image).encode("utf-8"))
        else:
            digest.update(("%s|%d,%d,%d,%d\n"
                           % (image, math.floor(coords[0]), math.floor(coords[1]),
                              math.floor(coords[2]), math.floor(coords[3]))).encode("utf-8"))
    return digest.hexdigest()


def measure():
    """The correct-localisation rate at IoU %s over the PRIVATE SPLIT.

    The denominator is the size of the graded split and never the number of images the submission
    chose to answer, so an omitted image is a miss and answering fewer images can only lower the
    rate. The comparison is inclusive: a box at exactly the threshold counts.
    """ % IOU_THRESHOLD
    truth = json_index(GRADED_BOXES)
    if not truth:
        raise ConstantUnmeasured("the private box index has not landed; the rate has no "
                                 "denominator and reporting 0.0 would assert the agent missed "
                                 "every image")
    try:
        table = load_submission()
    except Exception:
        table = {}
    localised = 0
    for image in sorted(truth):
        entry = table.get(image)
        if entry is None:
            continue
        try:
            coords, _ = top_box(entry)
        except Exception:
            continue
        if coords is None:
            continue
        reference = [as_number(value) for value in truth[image]] \
            if isinstance(truth[image], list) and len(truth[image]) == 4 else [None]
        if None in reference:
            continue
        if intersection_over_union(coords, reference) >= IOU_THRESHOLD:
            localised += 1
    return localised / float(len(truth))


def run_record():
    """What the graded run declared about itself.

    The agent writes this file, so it can be absent, truncated, or not JSON at all. Every one of
    those is an empty record here: an unparseable declaration declares nothing, and each check
    then reports its own missing-declaration reason instead of taking the verifier down with a
    decode error and returning no report about anything.
    """
    if not os.path.exists(RUN_RECORD):
        return {}
    try:
        with open(RUN_RECORD) as handle:
            doc = json.load(handle)
    except Exception:
        return {}
    return doc if isinstance(doc, dict) else {}


def declared_ids(key):
    """One declared image-id set from the record, or None when it was never declared."""
    value = run_record().get(key)
    if isinstance(value, dict):
        value = list(value)
    if not isinstance(value, list):
        return None
    return set(str(item) for item in value)


def declared_paths(key):
    """One declared path list from the record, or None when it was never declared."""
    value = run_record().get(key)
    if not isinstance(value, list):
        return None
    return [str(item) for item in value]


def in_guarded_tree(path):
    """True when a declared write lands on the checker tree or on a shipped index."""
    text = str(path).replace("\\", "/")
    return any(marker in text for marker in GUARDED_WRITES)


def names_a_trimap(path):
    """True when a declared read names the per-pixel supervision this slot withholds."""
    text = str(path).replace("\\", "/").lower()
    return any(token in text for token in TRIMAP_TOKENS)


def tree_holds_trimaps():
    """True when the withheld trimap directory exists in the delivered tree after all."""
    return os.path.exists(WITHHELD_TRIMAP_DIR)
